preConditionHook:
// THE CHANNEL START, the same level ChannelStartRetestEntry uses, so the whole
// family agrees on where a channel begins: it is SwingLow Occurrence 2 -- the
// OLDER of the two anchors the bull trend line is drawn through. The start of
// the channel is therefore the start of the line every other rule in the family
// draws, and pivotLookback is what says how far back 'the start' may be. The
// BEAR channel's start is the mirror, SwingHigh Occurrence 2.
//
// The pivot scan is INLINED rather than reaching into SwingHigh.json -- rules
// in this corpus never reference each other -- and mirrors the EL twin's
// SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR ABOVE the pivotStrength OLDER bars, STRICTLY ABOVE the
// pivotStrength NEWER bars -- so a flat top yields exactly one pivot, the later
// of the equal bars; bars-ago indexing makes the SMALLER index the NEWER bar,
// so the strict half is the k < j loop. The confirmation lag is exactly
// pivotStrength bars, never 0 or 1. pivotLookback is EL's Length (offsets
// 0..pivotLookback-1 inclusive) and the neighbourhood test reaches pivotStrength
// bars PAST the window, so the deepest index the scan touches is
// pivotLookback - 1 + pivotStrength. A window with fewer than two pivots is the
// -1 SENTINEL case, guarded below, because -1 as a price sits under every real
// price AND as a bar count would run the extreme scan backwards. Occurrence 3+
// is UNMEASURED and never asked for. The comparisons carry the 2.22e-12
// relational tolerance, hence el_gt / el_ge. The low side's tie sense is the
// mirror of the measured high-side rule. No WFSafe_SwingLow exists, so plain EL
// governs.
//
// THIS RULE: Brooks's 'reverses back at least 25 percent in the direction of
// the trend' (T21-45) -- one of the few explicit numbers he gives for a
// channel. The long was taken at the channel start; take profit once price has
// travelled bounceFraction of the channel's own height back toward the
// channel's extreme. p359 warns the pattern's predictability ends at the
// bounce, which is the argument for a fixed fractional target and not a trail.
//
// THE CHANNEL'S HEIGHT is measured on the channel's OWN SPAN, not on a fixed
// window: the extreme is the highest high between the current bar and the
// channel-start bar inclusive, which is why the loop bound is loB1 and not an
// input. Written as an explicit loop rather than EL's Highest over a variable Length
// because the register measures Highest's Length as a constant per bar and a
// variable in that slot is unmeasured; the loop is the same scan spelled out,
// statement for statement in both twins.
//
// chanExtHi > loP1 is the rule's own guard: a degenerate span makes the
// fraction meaningless and would put the target at the entry level.
//
// Related but distinct from RangeMidpointTarget, which is the FIXED 50% of a
// DONCHIAN window ending one bar ago. Here the fraction is an input, the
// anchors are the channel's own pivot and extreme, and the window ends on the
// current bar.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivS = (int)pivotStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 2) { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 2) { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoAnchor = (foundLo == 2) && (loB1 != -1.0);
haveHiAnchor = (foundHi == 2) && (hiB1 != -1.0);
chanExtHi = 0.0;
chanExtLo = 0.0;
targetUp = 0.0;
targetDn = 0.0;
haveTargetUp = false;
haveTargetDn = false;
if (haveLoAnchor) {
    chanExtHi = high[0];
    for (int kk = 1; kk <= (int)loB1; ++kk) {
        if (el_gt(high[kk], chanExtHi)) chanExtHi = high[kk];
    }
    if (el_gt(chanExtHi, loP1)) {
        targetUp = loP1 + bounceFraction * (chanExtHi - loP1);
        haveTargetUp = true;
    }
}
if (haveHiAnchor) {
    chanExtLo = low[0];
    for (int kk = 1; kk <= (int)hiB1; ++kk) {
        if (el_lt(low[kk], chanExtLo)) chanExtLo = low[kk];
    }
    if (el_gt(hiP1, chanExtLo)) {
        targetDn = hiP1 - bounceFraction * (hiP1 - chanExtLo);
        haveTargetDn = true;
    }
}
